        if ($source === $realUnit) {
            $unitFound = true;
            $value = $values[$source];
            $result += $value;
            $cumulativeFactor = 1;
        }

        if ($factor === false) {
            if ($unitFound) {
                break;
            }

            $result = 0;
            $cumulativeFactor = 0;

            continue;
        }

        if ($target === $realUnit) {
            $unitFound = true;
        }

