/**
 * Round the current instance at the given unit with given precision if specified and the given function.
 *
 * @param string                             $unit
 * @param float|int|string|DateInterval|null $precision
 * @param string                             $function
 *
 * @throws Exception
 *
 * @return $this
 */
public function roundUnit($unit, $precision = 1, $function = 'round')
{
    $base = CarbonImmutable::parse('2000-01-01 00:00:00', 'UTC')
        ->roundUnit($unit, $precision, $function);
    $next = $base->add($this);
    $inverted = $next < $base;

    if ($inverted) {
        $next = $base->sub($this);
    }

    $language = new Language($this->locale ?? 'en');
    $immutableFactory = new FactoryImmutable([
        'timezone' => 'UTC',
        'locale' => $language->getId(),
    ]);
    $settings = $immutableFactory->getSettings();
    $anchor = (new Factory($settings))->instance($next);
    $timezone = $anchor->timezone;
    $rebuiltNext = $immutableFactory->create(
        $anchor->year,
        $anchor->month,
        $anchor->day,
        $anchor->hour,
        $anchor->minute,
        $anchor->second + $anchor->micro / 1000000,
        $timezone->getName()
    );
    $window = CarbonPeriod::create($base, $rebuiltNext->roundUnit($unit, $precision, $function));
    $this->copyProperties(
        $window->getEndDate()->diffAsCarbonInterval($window->getStartDate())
    );

    return $this->invert($inverted);
}

